def sortTransformed(nums, a, b, c):
    def f(x):
        return a * x * x + b * x + c
    n = len(nums)
    res = [0] * n
    l, r = 0, n - 1
    if a >= 0:
        pos = n - 1
        while l <= r:
            fl, fr = f(nums[l]), f(nums[r])
            if fl > fr:
                res[pos] = fl
                l += 1
            else:
                res[pos] = fr
                r -= 1
            pos -= 1
    else:
        pos = 0
        while l <= r:
            fl, fr = f(nums[l]), f(nums[r])
            if fl < fr:
                res[pos] = fl
                l += 1
            else:
                res[pos] = fr
                r -= 1
            pos += 1
    return res
